  "language": "en",
  "style": {
    "theme": "editorial",
    "audience": "researchers and policy makers",
    "tone": "informative, impactful, publication-ready"
  },
  "goal": [
    {
      "id": "supply-chain-waste-flow",
      "insight": "Show the flow of food waste across the four supply chain stages (production, processing, retail, consumption) as a composition, making the relative magnitude of waste at each stage visually prominent"
    },
    {
      "id": "carbon-waste-alignment",
      "insight": "Visually juxtapose each stage's waste share with its corresponding carbon emission contribution, highlighting stages where carbon intensity is disproportionate to waste volume"
    },
    {
      "id": "avoidable-waste-overlay",
      "insight": "Overlay or annotate the proportion of avoidable waste within each stage to make high-intervention-potential stages visually distinct"
    },
    {
      "id": "regional-variation-pattern",
      "insight": "Compare waste distribution patterns across regions (e.g., high-income vs low-income countries) to emphasize how supply chain hotspots shift geographically"
    },
    {
      "id": "intervention-priority-signal",
      "insight": "Emphasize the stages and regions where high avoidable waste and high carbon emissions converge, visually signaling priority intervention points"
    }
  ]
}

